  str_files_story_title_5305 = "The Gold of Happiness III",
  str_files_story_des_101 = "Semua orang kecuali Nikinis telah mengisi Formulir Informasi Dasar. Mengapa dia begitu enggan mengisinya…?",
  str_files_story_des_103 = "Tanpa dinyana, aku bertemu dengan dua Nikinis! Mungkinkah salah satu dari mereka adalah kakak perempuan yang terus-menerus disebutnya?! Mereka benar-benar mirip…",
  str_files_story_des_105 = "Story 5",
  str_files_story_des_107 = "Story 7",
  str_files_story_des_110 = "Story 10",
  str_files_story_des_201 = "Kau bisa merasakan tatapan intens dari seseorang yang mengikutimu ke mana-mana belakangan ini. Untuk memancing si penguntit agar mau menunjukkan diri, kau berpura-pura menjadi orang canggung…",
  str_files_story_des_203 = "Atasanmu ternyata orangnya sangat santai, tetapi aura yang kuat itu masih membuatmu tidak yakin. Kau punya pertanyaan yang mungkin ingin kau ajukan…",
  str_files_story_des_205 = "Story 5",
  str_files_story_des_207 = "Story 7",
  str_files_story_des_209 = "Story 9",
  str_files_story_des_210 = "Story 10",
  str_files_story_des_402 = "Story 2",
  str_files_story_des_404 = "Story 4",
  str_files_story_des_406 = "Story 6",
  str_files_story_des_408 = "Story 8",
  str_files_story_des_501 = "Story 1",
  str_files_story_des_503 = "Story 3",
  str_files_story_des_505 = "Story 5",
  str_files_story_des_507 = "Story 7",
  str_files_story_des_509 = "Story 9",
  str_files_story_des_510 = "Story 10",
  str_files_story_des_602 = "Tampaknya tidak mudah berurusan dengan putri City Lord. Kau mencoba untuk menunjukkan kualitas kepemimpinanmu, tetapi…",
  str_files_story_des_604 = "Carleen tampaknya sedang dalam dilema. Mengingat kau tidak cukup peka akan perasaan orang lain, bagaimana kau akan mencoba?",
  str_files_story_des_606 = "Story 6",
  str_files_story_des_608 = "Story 8",
  str_files_story_des_609 = "Story 9",
  str_files_story_des_610 = "Story 10",
  str_files_story_des_802 = "Story 2",
  str_files_story_des_804 = "Story 4",
  str_files_story_des_806 = "Story 6",
  str_files_story_des_901 = "Story 1",
  str_files_story_des_903 = "Story 3",
  str_files_story_des_905 = "Story 5",
  str_files_story_des_907 = "Story 7",
  str_files_story_des_910 = "Story 10",
  str_files_story_des_1002 = "Story 2",
  str_files_story_des_1004 = "Story 4",
  str_files_story_des_1006 = "Story 6",
  str_files_story_des_1008 = "Story 8",
  str_files_story_des_1009 = "Story 9",
  str_files_story_des_1102 = "Hari ini bukanlah hari inspeksi biasa, tetapi kau merasakan tekanan yang berat karena Sharona, sang Illumina Commander, akan mengomentari operasi Colossus! Semoga semua berjalan lancar…",
  str_files_story_des_1104 = "Sharona, yang sangat memperhatikanmu dan Colossus, tampaknya punya alasannya sendiri. Mungkin dia telah melihat sesuatu dalam dirimu yang memenuhi harapannya…",
  str_files_story_des_1106 = "Story 5",
  str_files_story_des_1108 = "Story 7",
  str_files_story_des_1110 = "Story 10",
  str_files_story_des_1201 = "Perdebatan yang sengit tentang hal-hal yang sepele bisa terdengar dari Colossus! Suka atau tidak suka, sepertinya kau harus menjadi penengah…",
  str_files_story_des_1203 = "Nemesis tampaknya sangat terobsesi dengan kejujuran dan keadilan. Mungkin kau harus meluangkan lebih banyak waktu untuk mengobrol dengannya dan mengetahui sisi tersembunyi dirinya…",
  str_files_story_des_1205 = "Story 5",
  str_files_story_des_1207 = "Story 7",
  str_files_story_des_1210 = "Story 10",
  str_files_story_des_1302 = "Story 2",
  str_files_story_des_1304 = "Story 4",
  str_files_story_des_1306 = "Story 6",
  str_files_story_des_1308 = "Story 8",
  str_files_story_des_1309 = "Story 9",
  str_files_story_des_1310 = "Story 10",
  str_files_story_des_1402 = "City Lord menginspeksi Colossus secara langsung?! Karena kebingungan, kau terlambat sejak awal. Sebaiknya kau berusaha sebaik mungkin agar tidak membuat kesalahan lagi!",
  str_files_story_des_1404 = "Mengapa City Lord yang ramah mendekatimu secara agresif? Apa yang terjadi?! Sebagai penanggung jawab Colossus, sekali lagi kau merasakan tatapan yang menyiratkan harapan dan kekecewaan…",
  str_files_story_des_1406 = "Story 6",
  str_files_story_des_1408 = "Story 8",
  str_files_story_des_1409 = "Story 9",
  str_files_story_des_1410 = "Story 10",
  str_files_story_des_1701 = "Story 1",
  str_files_story_des_1703 = "Story 3",
  str_files_story_des_1705 = "Story 5",
  str_files_story_des_1707 = "Story 7",
  str_files_story_des_1802 = "Undangan pertunjukan musik langsung? Sementara kau sedang ragu apakah kau harus hadir dalam acara aneh ini alih-alih beristirahat, kau mendengar ketukan keras di pintu…",
  str_files_story_des_1804 = "Hari yang ditunggu-tunggu telah tiba. Kau bertanya-tanya akan seperti apa pertunjukan musik langsung Regina. Perasaan tidak nyaman pun mulai menghantuimu—",
  str_files_story_des_1806 = "Story 6",
  str_files_story_des_1808 = "Story 8",
  str_files_story_des_1809 = "Story 9",
  str_files_story_des_1810 = "Story 10",
  str_files_story_des_1901 = "Story 1",
  str_files_story_des_1903 = "Story 3",
  str_files_story_des_1905 = "Story 5",
  str_files_story_des_1907 = "Story 7",
  str_files_story_des_1910 = "Story 10",
  str_files_story_des_2101 = "Story 1",
  str_files_story_des_2103 = "Story 3",
  str_files_story_des_2105 = "Story 5",
  str_files_story_des_2107 = "Story 7",
  str_files_story_des_2201 = "Story 1",
  str_files_story_des_2203 = "Story 3",
  str_files_story_des_2205 = "Story 5",
  str_files_story_des_2301 = "Story 3",
  str_files_story_des_2303 = "Story 5",
  str_files_story_des_2305 = "Story 7",
  str_files_story_des_2307 = "Story 9",
  str_files_story_des_2310 = "Story 10",
  str_files_story_des_2501 = "Seperti hari-hari lain, hari ini kau mendapatkan banyak keluhan tentang Charon. Waktunya berbicara dengannya.",
  str_files_story_des_2503 = "Mengobrol biasa dengan Charon itu mustahil. Berusahalah sebaik mungkin demi mendapatkan lebih banyak informasi dan mungkin kau akan mengetahui obsesinya.",
  str_files_story_des_2505 = "Story 5",
  str_files_story_des_2507 = "Story 7",
  str_files_story_des_2509 = "Story 9",
  str_files_story_des_2510 = "Story 10",
  str_files_story_des_2602 = "Story 2",
  str_files_story_des_2604 = "Story 4",
  str_files_story_des_2606 = "Story 6",
  str_files_story_des_2608 = "Story 8",
  str_files_story_des_2609 = "Story 9",
  str_files_story_des_2610 = "Story 10",
  str_files_story_des_2801 = "Kau terus merasa sesuatu yang buruk akan terjadi… Apa itu? Ah, apakah itu Raphael? Kenapa dia melambai… seperti orang gila?",
  str_files_story_des_2803 = "Upaya Raphael untuk meningkatkan pengobatan medis cukup merepotkan. Semoga dia tidak melakukan sesuatu yang merepotkan hari ini. Jika tidak, bahkan kau pun akan mengajukan keluhan…",
  str_files_story_des_2805 = "Story 5",
  str_files_story_des_2807 = "Story 7",
  str_files_story_des_2809 = "Story 9",
  str_files_story_des_2810 = "Story 10",
  str_files_story_des_2902 = "Story 2",
  str_files_story_des_2904 = "Story 4",
  str_files_story_des_2906 = "Story 6",
  str_files_story_des_2908 = "Story 8",
  str_files_story_des_2909 = "Story 9",
  str_files_story_des_2910 = "Story 10",
  str_files_story_des_3202 = "Story 2",
  str_files_story_des_3204 = "Story 4",
  str_files_story_des_3206 = "Story 6",
  str_files_story_des_3301 = "Pertanyaan: Seberapa baik kau mengenal teman lama yang kongko denganmu setiap hari? Tahukah kau apa yang sebenarnya dipikirkannya? Mungkin jawabannya terkubur dalam…",
  str_files_story_des_3303 = "Mengapa survei bersama Vice terasa lebih seperti ulasan? Kau gugup dan berharap Vice bersikap lunak padamu, terlepas dari apa pun itu…",
  str_files_story_des_3305 = "Story 6",
  str_files_story_des_3307 = "Story 8",
  str_files_story_des_3310 = "Story 10",
  str_files_story_des_3501 = "Akhir-akhir ini, Eho kerap terlambat mengantarkan kiriman. Mengapa begitu? Cobalah membicarakannya…",
  str_files_story_des_3503 = "Ternyata Eho gampang tersesat… Pasti sangat sulit baginya untuk melakukan pekerjaannya… Jadi, apakah menyalin peta bisa benar-benar membantunya mengingat…?",
  str_files_story_des_3505 = "Story 5",
  str_files_story_des_3602 = "Story 1",
  str_files_story_des_3604 = "Story 3",
  str_files_story_des_3606 = "Story 5",
  str_files_story_des_3608 = "Story 7",
  str_files_story_des_3610 = "Story 10",
  str_files_story_des_3802 = "Gronru sangat prihatin dengan perawatan Colossus baru-baru ini dan tampaknya sangat tertarik dan antusias tentang hal itu. Kalian akan mengadakan rapat resmi pertama hari ini. Penasaran seperti apa kepribadiannya?",
  str_files_story_des_3804 = "Sepertinya Gronru sangat suka bermain game… Kuharap kesukaannya ini tidak memengaruhi pekerjaan sehari-harinya. Jika tidak, akan sulit untuk menanganinya…",
  str_files_story_des_3806 = "Story 6",
  str_files_story_des_3808 = "Story 8",
  str_files_story_des_3809 = "Story 9",
  str_files_story_des_3810 = "Story 10",
  str_files_story_des_4001 = "Story 1",
  str_files_story_des_4003 = "Story 3",
  str_files_story_des_4005 = "Story 5",
  str_files_story_des_4007 = "Story 7",
  str_files_story_des_4101 = "Ms. Blanc selalu supersibuk untuk acara-acara besar. Cobalah kau temui dia. Alih-alih menghalangi, lebih baik lagi jika kau bisa membantu…",
  str_files_story_des_4103 = "Hmm… Sepertinya kau benar-benar memperburuk keadaan. Ms. Blanc kini jadi lebih sibuk… Mungkin kau bisa memperbaikinya?",
  str_files_story_des_4105 = "Story 5",
  str_files_story_des_4107 = "Story 7",
  str_files_story_des_4402 = "Story 2",
  str_files_story_des_4404 = "Story 4",
  str_files_story_des_4406 = "Story 6",
  str_files_story_des_4408 = "Story 8",
  str_files_story_des_4601 = "Story 1",
  str_files_story_des_4603 = "Story 3",
  str_files_story_des_4605 = "Story 5",
  str_files_story_des_4701 = "Zoya bertingkah aneh belakangan ini, serampangan dan sulit dipahami. Tampaknya… dia sedang mengamati sesuatu?",
  str_files_story_des_4703 = "Jadi, Zoya bergantung pada Madam Hiiro dengan cara khusus. Kau ingin tahu kenapa begitu dan apakah dia benar-benar akan berbagi cerita?",
  str_files_story_des_4705 = "Story 5",
  str_files_story_des_4801 = "Sebagai penanggung jawab Colossus, mengumpulkan informasi juga termasuk bagian dari pekerjaan yang sepertinya berlaku dalam mengarungi perjalanan bersama Dayna.",
  str_files_story_des_4803 = "Sudah pasti, pekerjaan karavan tidaklah semudah itu… Setelah berjalan entah berapa jauh dengan Dayna, kau hampir tidak bisa berdiri, apalagi mengumpulkan intel…",
  str_files_story_des_4805 = "Story 5",
  str_files_story_des_4807 = "Story 7",
  str_files_story_des_4902 = "Story 2",
  str_files_story_des_4904 = "Story 4",
  str_files_story_des_4906 = "Story 6",
  str_files_story_des_5001 = "Story 1",
  str_files_story_des_5003 = "Story 3",
  str_files_story_des_5005 = "Story 5",
  str_files_story_des_5101 = "Story 1",
  str_files_story_des_5103 = "Story 3",
  str_files_story_des_5105 = "Story 5",
  str_files_story_des_5201 = "Story 2",
  str_files_story_des_5203 = "Story 4",
  str_files_story_des_5205 = "Story 6",
  str_files_story_des_5301 = "Jomu tentunya salah satu orang yang mendapatkan banyak surat keluhan. Caranya mempromosikan dan menjual barang secara gegabah sangat menyebalkan. Kuharap aku tidak akan bertemu dengannya hari ini…",
  str_files_story_des_5303 = "Mengapa Jomu bekerja sangat keras demi uang? Tampaknya dia tidak punya kebiasaan yang merugikan. Mungkin ada cerita di baliknya?",
  str_files_story_des_5305 = "Story 5",
